    "subtopicId": "words-in-context",
    "subtopic": "Words in context",
    "difficulty": "hard",
    "passage": "Scholarly discussions of gender in Shakespeare’s comedies often celebrate the rebellion of the playwright’s characters against the rigid expectations ______ by Elizabethan society. Most of the comedies end in marriage, with characters returning to their socially dictated gender roles after previously defying them, but there are some notable exceptions.",
